python - <<'PY'
import urllib.request,zipfile,io,json,math
z=zipfile.ZipFile(io.BytesIO(urllib.request.urlopen('https://raw.githubusercontent.com/Seshat-Global-History-Databank/cliopatria/main/cliopatria.geojson.zip').read()))
x=json.load(z.open(z.namelist()[0]))
# RDP simplification for rings, map view lon -13..49 lat 33..63. tolerance ~0.08 degrees.
def dist(p,a,b):
 dx=b[0]-a[0];dy=b[1]-a[1]
 if dx==dy==0:return math.hypot(p[0]-a[0],p[1]-a[1])
 t=max(0,min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)))
 return math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)
def rdp(pts,eps):
 if len(pts)<3:return pts
 m=0;idx=0
 for i in range(1,len(pts)-1):
  d=dist(pts[i],pts[0],pts[-1])
  if d>m:m=d;idx=i
 if m>eps:return rdp(pts[:idx+1],eps)[:-1]+rdp(pts[idx:],eps)
 return [pts[0],pts[-1]]
def ringpath(ring):
 pts=rdp([p[:2] for p in ring],0.07)
 xy=[(50+(lon+13)*12.8,(63-lat)*20) for lon,lat in pts]
 return 'M'+' '.join((f'{a:.1f},{b:.1f}' if i==0 else f'{a:.1f},{b:.1f}') for i,(a,b) in enumerate(xy))+'Z'
def geompath(g):
 polys=g['coordinates'] if g['type']=='MultiPolygon' else [g['coordinates']]
 return ' '.join(ringpath(r) for poly in polys for r in poly)
selected={'Kingdom of England':'harold','Duchy of Normandy':'normandy','Kingdom of France':'philip',"Kievan Rus'":'iziaslav','Byzantine Empire':'constantine','Norman Italy':'robert'}
items=[]
for f in x['features']:
 p=f['properties']
 if not(p['FromYear']<=1066<=p['ToYear']): continue
 if p.get('Type')!='POLITY': continue
 n=p['Name']
 if n in selected: items.append((n,selected[n],geompath(f['geometry']),True))
 elif n.startswith('('): continue
 else:
  # geographic bbox intersection rough and only polygon min longitude < 49 / max > -13
  def walk(c,lo=[999],hi=[-999]):
   if isinstance(c[0],(float,int)):lo[0]=min(lo[0],c[0]);hi[0]=max(hi[0],c[0])
   else:
    for q in c:walk(q,lo,hi)
   return lo[0],hi[0]
  lo,hi=walk(f['geometry']['coordinates'])
  if lo<49 and hi>-13:items.append((n,'background',geompath(f['geometry']),False))
# save as SVG group
out=[]
for n,id,d,play in items:
 if play: out.append(f'<path class="territory selectable" data-polity="{id}" aria-label="{n}" d="{d}"/>')
 else: out.append(f'<path class="territory context" d="{d}"/>')
open('/tmp/polities.svg','w').write('\n'.join(out))
print('features',len(items),'interactive',sum(x[3] for x in items),'size',sum(map(len,out)))
for i in items:
 if i[3]:print(i[0],len(i[2]))
PY

