function seasonName(date){const month=new Date(`${date}T12:00:00Z`).getUTCMonth();return ['Winter','Winter','Winter','Spring','Spring','Spring','Summer','Summer','Summer','Autumn','Autumn','Autumn'][month];}
function clamp(value,min=0,max=100){return Math.max(min,Math.min(max,value));}
function addChronicle(title,copy,date=dateText(game.date)){game.log.unshift({date,title,copy});game.log=game.log.slice(0,10);}
function actionButton(id,title,detail,cost,enabled){return `<button class="strategy-action" data-command="${id}" ${enabled?'':'disabled'}><span><b>${title}</b><small>${detail}</small></span><span class="action-cost">${cost}<em>1 action</em></span></button>`;}
function renderGame(){if(!game)return;const r=rulers[game.ruler],events=game.log.map(item=>`<article class="event"><div class="event-date">${item.date}</div><h3 class="event-title">${item.title}</h3><p class="event-copy">${item.copy}</p></article>`).join(''),available=game.actionsLeft>0;document.getElementById('appDate').textContent=dateText(game.date);document.getElementById('campaignSidebar').innerHTML=`<p class="sidebar-kicker">Your chronicle · ${r.realm}</p><h1 class="sidebar-title">${r.name}</h1><p class="sidebar-subtitle">${r.seal} · ${seasonName(game.date)} ${new Date(`${game.date}T12:00:00Z`).getUTCFullYear()}</p><div class="stats-grid"><div class="stat"><div class="stat-label">Treasury</div><div class="stat-value">${game.gold}</div></div><div class="stat"><div class="stat-label">Levies</div><div class="stat-value">${game.levies}</div></div><div class="stat"><div class="stat-label">Legitimacy</div><div class="stat-value">${game.legitimacy}</div></div><div class="stat"><div class="stat-label">Court cohesion</div><div class="stat-value">${game.cohesion}</div></div><div class="stat"><div class="stat-label">Influence</div><div class="stat-value">${game.influence}</div></div><div class="stat"><div class="stat-label">Rival pressure</div><div class="stat-value">${game.threat}</div></div></div><div class="season-track"><strong>${game.actionsLeft} of 3 actions remain</strong><small>Season ${game.turn} · each turn advances about three months. Unused actions are lost at season’s end.</small></div><p class="strategy-meter"><span>Diplomatic standing</span><b>${game.standing>0?'+':''}${game.standing} / 5</b></p><p class="campaign-copy">${game.objective}</p><h2 class="history-title">Council & realm actions</h2><div class="action-grid">${actionButton('muster','Muster forces','Add five levy units; pressure on local communities strains cohesion.','12 treasury',available&&game.gold>=12)}${actionButton('govern','Settle the realm','Invest in administration: strengthen cohesion, legitimacy, and future income.','8 treasury',available&&game.gold>=8)}${actionButton('diplomacy','Seek an accord','Improve standing with rival courts and ease external pressure.','6 treasury',available&&game.gold>=6&&game.standing<5)}${actionButton('council','Win council support','Spend influence to bolster legitimacy and court cohesion.','2 influence',available&&game.influence>=2)}${actionButton('campaign','Secure the frontier','Use forces and funds to push back pressure; no battle outcome is simulated.','6 levies · 10 treasury',available&&game.levies>=6&&game.gold>=10)}${actionButton('intrigue','Political maneuver','Spend influence to unsettle rival coordination; legitimacy may suffer.','2 influence',available&&game.influence>=2)}</div><button class="season-button" data-command="turn">Resolve season · ${game.actionsLeft} unused</button><p class="rules-note">Three major actions are available each season. Rival courts also muster, consolidate, or press claims; seasonal revenue, internal cohesion, and political pressure then update.</p><div class="history-box"><h2 class="history-title">Chronicle</h2><div class="event-list">${events}</div></div><p class="provenance">Ruler details and event context: ${r.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`).join(' · ')}</p>`;updateMapSelection();}
function renderScreen(){if(campaignApp.dataset.screen==='game')renderGame();else renderSetup();}
function updateMapSelection(){document.querySelectorAll('.territory[data-polity]').forEach(p=>p.classList.toggle('is-selected',p.dataset.polity===chosenRuler));}
function newRivalState(){return {gold:58,levies:18,legitimacy:58,cohesion:52};}
function startGame(){if(!chosenRuler)return;const r=rulers[chosenRuler],threat={harold:44,philip:30,constantine:48,iziaslav:45,robert:36}[chosenRuler],cohesion={harold:58,philip:62,constantine:52,iziaslav:44,robert:49}[chosenRuler],objectives={harold:'Hold the crown together while managing threats across the Channel and North Sea. Pressure and legitimacy—not a scripted battle—shape this campaign.',philip:'Build Capetian authority among powerful principalities; choose when to govern, bargain, or mobilize.',constantine:'Balance imperial resources and court cohesion against pressure on distant frontiers and the succession ahead.',iziaslav:'Preserve princely cooperation and Kyiv’s authority; internal cohesion is as important as external pressure.',robert:'Keep a coalition of Norman lords aligned while building the resources to pursue an ambitious southern policy.'};game={ruler:chosenRuler,date:'1066-01-06',turn:1,actionsLeft:3,...r.start,cohesion,influence:3,standing:0,threat,incomeBonus:0,rival:newRivalState(),objective:objectives[chosenRuler],log:[{date:'6 January 1066',title:`${r.name} — a new reign`,copy:r.events[0][1]+'. '+r.events[0][2]}]};campaignApp.dataset.screen='game';renderGame();saveGame();}
function saveGame(){try{localStorage.setItem('ch-norman-save',JSON.stringify(game))}catch(e){showToast('This browser could not save the chronicle.')}}
function loadGame(){try{const saved=JSON.parse(localStorage.getItem('ch-norman-save'));if(saved&&rulers[saved.ruler]&&saved.date){game=saved;game.turn=game.turn||1;game.actionsLeft=Number.isInteger(game.actionsLeft)?clamp(game.actionsLeft,0,3):3;game.cohesion=Number.isFinite(game.cohesion)?game.cohesion:55;game.influence=Number.isFinite(game.influence)?game.influence:3;game.standing=Number.isFinite(game.standing)?game.standing:0;game.threat=Number.isFinite(game.threat)?game.threat:35;game.incomeBonus=Number.isFinite(game.incomeBonus)?game.incomeBonus:0;game.rival=game.rival||newRivalState();game.objective=game.objective||'Balance authority, resources, and pressure from rival courts.';game.log=Array.isArray(game.log)?game.log:[];chosenRuler=saved.ruler;enterApp('game');return true}}catch(e){}return false}
function performAction(command){if(!game||game.actionsLeft<=0)return;const rival=game.rival;let title='',copy='';if(command==='muster'&&game.gold>=12){game.gold-=12;game.levies+=5;game.cohesion=clamp(game.cohesion-2);title='Forces mustered';copy='Twelve treasury funds five additional levy units. The new demands place a small strain on court cohesion.';}else if(command==='govern'&&game.gold>=8){game.gold-=8;game.cohesion=clamp(game.cohesion+4);game.legitimacy=clamp(game.legitimacy+2);game.incomeBonus=clamp(game.incomeBonus+1,0,6);title='The realm is administered';copy='Investment in local administration improves cohesion and legitimacy, and adds one treasury to future seasonal income.';}else if(command==='diplomacy'&&game.gold>=6&&game.standing<5){game.gold-=6;game.standing=clamp(game.standing+2,-5,5);game.threat=clamp(game.threat-3);title='An accord sought';copy='Gifts and envoys improve diplomatic standing and ease rival pressure. The agreement is represented abstractly; no specific treaty is presumed.';}else if(command==='council'&&game.influence>=2){game.influence-=2;game.legitimacy=clamp(game.legitimacy+4);game.cohesion=clamp(game.cohesion+3);title='Council support secured';copy='The ruler spends political influence to strengthen legitimacy and court cohesion.';}else if(command==='campaign'&&game.gold>=10&&game.levies>=6){game.gold-=10;game.levies-=6;game.threat=clamp(game.threat-8);game.standing=clamp(game.standing+1,-5,5);game.cohesion=clamp(game.cohesion-1);title='The frontier is secured';copy='Six levy units and ten treasury are committed to a show of force, reducing rival pressure at a cost to the realm. No battle or territorial outcome is resolved.';}else if(command==='intrigue'&&game.influence>=2){game.influence-=2;rival.cohesion=clamp(rival.cohesion-5);game.threat=clamp(game.threat-2);game.legitimacy=clamp(game.legitimacy-1);title='A political maneuver';copy='A covert courtly maneuver disrupts rival coordination and slightly eases pressure, but the ruler’s legitimacy suffers if the action is exposed.';}else return;game.actionsLeft--;addChronicle(title,copy);renderGame();saveGame();}
function endTurn(){if(!game)return;const oldDate=game.date,d=new Date(`${oldDate}T12:00:00Z`);d.setUTCMonth(d.getUTCMonth()+3);game.date=d.toISOString().slice(0,10);game.turn++;game.actionsLeft=3;const rival=game.rival;let mustered=0,consolidated=0,challenged=0;rival.gold+=8;for(let i=0;i<3;i++){if(rival.levies<24&&rival.gold>=12){rival.gold-=12;rival.levies+=4;mustered++;}else if(rival.cohesion<60&&rival.gold>=8){rival.gold-=8;rival.cohesion=clamp(rival.cohesion+4);rival.legitimacy=clamp(rival.legitimacy+1);consolidated++;}else if(rival.gold>=6){rival.gold-=6;let push=2+(rival.levies>game.levies+8?1:0)-(game.standing>=2?1:0);game.threat=clamp(game.threat+Math.max(1,push));challenged++;}}game.gold=Math.max(0,game.gold+8+game.incomeBonus+Math.floor(game.cohesion/35));game.influence=clamp(game.influence+1,0,9);game.cohesion=clamp(game.cohesion+(game.legitimacy>=75?1:0)-(game.legitimacy<40?3:0));if(game.threat>=70)game.legitimacy=clamp(game.legitimacy-2);if(game.cohesion<25)game.legitimacy=clamp(game.legitimacy-2);const rivalActs=[mustered?`mustered ${mustered} time${mustered===1?'':'s'}`:'',consolidated?`consolidated ${consolidated} time${consolidated===1?'':'s'}`:'',challenged?`pressed claims ${challenged} time${challenged===1?'':'s'}`:''].filter(Boolean).join(', ')||'reorganized its court';addChronicle(`${seasonName(oldDate)} season resolved`,`Rival courts ${rivalActs}. Your treasury receives seasonal revenue; court cohesion and political influence are updated.`);const year=d.getUTCFullYear(),month=d.getUTCMonth(),markerKey=`${game.ruler}-${year}-${month}`;const marker=(game.ruler==='harold'&&year===1066&&month===8)||(game.ruler==='iziaslav'&&year===1068&&month===8)||(game.ruler==='constantine'&&year===1067&&month===11);if(marker&&game.lastMarker!==markerKey){const note=rulers[game.ruler].events[2];addChronicle(note[1],note[2]+' Historical context only: this date does not force the campaign outcome.');game.lastMarker=markerKey;}renderGame();saveGame();}

