211: <script>
212: const modal=document.getElementById('modal'),panel=document.getElementById('panel'),toast=document.getElementById('toast'),campaignApp=document.getElementById('campaignApp');let previousFocus=null,chosenRuler=null,game=null;
213: const rulers={
214:  harold:{name:'Harold II Godwinson',realm:'Kingdom of England',short:'England',mark:'H',difficulty:'High · exposed',seal:'House of Godwin',bio:'Crowned at Westminster on 6 January 1066, Harold inherited a kingdom facing rival claims and threats across the Channel and North Sea. The campaign opens on the day of his coronation.',why:'A compact realm with strong local resources, but three dynastic claimants and a narrow window to act.',start:{gold:78,levies:24,legitimacy:72},events:[['6 Jan 1066','A contested crown','Harold is crowned king after Edward the Confessor’s death. His authority will be tested by rival claims.'],['Spring 1066','Watch the coasts','William of Normandy prepares to press his claim; the northern threat is also gathering.'],['September 1066','The northern invasion','Historically, Harald Hardrada and Tostig landed in the north before Harold’s march to face them.']],sources:[['Royal Family: Harold II','https://www.royal.uk/harold-ii-r-jan-oct-1066'],['Encyclopaedia Britannica: Harold II','https://www.britannica.com/biography/Harold-II']]},
215:  philip:{name:'Philip I',realm:'Kingdom of France',short:'France',mark:'P',difficulty:'Moderate · young king',seal:'House of Capet',bio:'Philip became king in 1060 as a child. His mother, Anne of Kyiv, and Baldwin V of Flanders acted as regents during his minority; by 1066 the young Capetian king was beginning to rule in his own right.',why:'A royal title and a growing dynasty, balanced by youthful rule and the limited reach of royal authority.',start:{gold:68,levies:20,legitimacy:66},events:[['1060','A child king','Philip succeeds his father Henry I at about eight years old; a regency governs during his minority.'],['1066','Coming of age','At fourteen, Philip begins to exercise kingship amid the powerful principalities of France.'],['1066','Across the Channel','William of Normandy is both a powerful vassal and a claimant to the English crown.']],sources:[['Encyclopaedia Britannica: Philip I','https://www.britannica.com/biography/Philip-I-king-of-France']]},
216:  constantine:{name:'Constantine X Doukas',realm:'Byzantine Empire',short:'Byzantium',mark:'C',difficulty:'High · imperial strains',seal:'House of Doukas',bio:'Constantine X ruled the Byzantine Empire from 1059 until his death in 1067. His reign sat within a period of mounting military and political pressure on the empire’s eastern frontiers.',why:'An imperial treasury and prestige, but a vast frontier to defend and a fragile succession ahead.',start:{gold:92,levies:27,legitimacy:69},events:[['1059','A new emperor','Constantine X succeeds Isaac I Komnenos, beginning the Doukas dynasty’s rule.'],['1066','Frontier pressures','The empire must manage military demands across distant and varied frontiers.'],['1067','A succession ahead','Constantine’s death in 1067 will leave Empress Eudokia and their son Michael central to succession.']],sources:[['Encyclopaedia Britannica: Constantine X','https://www.britannica.com/biography/Constantine-X-Ducas'],['Dumbarton Oaks: Constantine X','https://www.doaks.org/resources/online-exhibits/gods-regents-on-earth-a-thousand-years-of-byzantine-imperial-seals/rulers-of-byzantium/constantine-x-doukas-1059-67']]},
217:  iziaslav:{name:'Iziaslav I Yaroslavich',realm:'Kievan Rus’ · Kyiv',short:'Kievan Rus’',mark:'I',difficulty:'Very high · princely rivalries',seal:'Rurikid prince',bio:'Iziaslav, eldest son of Yaroslav the Wise, held Kyiv from 1054. His rule depended on cooperation among the senior princes, a balance that would break in 1068 when a popular revolt drove him from the city.',why:'A powerful seat but no simple centralized state: dynastic cooperation and local politics are crucial.',start:{gold:64,levies:23,legitimacy:61},events:[['1054','The princes’ settlement','After Yaroslav the Wise’s death, Iziaslav becomes senior prince in Kyiv alongside his brothers.'],['1066','A fragile accord','The princes’ shared order remains vulnerable to military reverses and disputes over authority.'],['1068','Revolt in Kyiv','Historically, defeat by the Cumans was followed by an uprising that forced Iziaslav to flee Kyiv.']],sources:[['Encyclopedia of Ukraine: Iziaslav Yaroslavich','https://www.encyclopediaofukraine.com/display.asp?linkpath=pages%5CI%5CZ%5CIziaslavYaroslavych.htm']]},
218:  robert:{name:'Robert Guiscard',realm:'Norman Italy · Apulia and Calabria',short:'Norman Italy',mark:'R',difficulty:'Moderate · expansionist',seal:'House of Hauteville',bio:'A Norman adventurer who became duke of Apulia and Calabria in 1059, Robert built power in southern Italy and continued campaigns against Byzantine holdings. His authority rested on a coalition of Norman lords.',why:'An ambitious military base with room to expand, but competing lords and neighboring powers demand attention.',start:{gold:72,levies:26,legitimacy:59},events:[['1059','Duke by papal grant','The Treaty of Melfi recognizes Robert as duke of Apulia, Calabria and future Sicily.'],['1061','The Sicilian campaign','Robert and his brother Roger begin the Norman conquest of Sicily.'],['1066','A divided south','Norman power has grown, but southern Italy remains a patchwork of rival authorities.']],sources:[['Encyclopaedia Britannica: Robert Guiscard','https://www.britannica.com/biography/Robert-Guiscard']]}
219: };
220: const realmKeys={harold:'harold',philip:'philip',constantine:'constantine',iziaslav:'iziaslav',robert:'robert'};
221: function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2500)}
222: function openModal(html){previousFocus=document.activeElement;panel.innerHTML=html;modal.classList.add('open');panel.querySelector('.close')?.focus()}
