 function endTurn(){if(!game)return;const oldDate=validDate(game.date)?game.date:'1066-01-06';game.date=oldDate;const d=new Date(`${oldDate}T12:00:00Z`);d.setUTCMonth(d.getUTCMonth()+3);game.date=d.toISOString().slice(0,10);game.turn++;game.actionsLeft=3;const rival=game.rival;let mustered=0,consolidated=0,challenged=0;rival.gold+=8;for(let i=0;i<3;i++){if(rival.levies<24&&rival.gold>=12){rival.gold-=12;rival.levies+=4;mustered++;}else if(rival.cohesion<60&&rival.gold>=8){rival.gold-=8;rival.cohesion=clamp(rival.cohesion+4);rival.legitimacy=clamp(rival.legitimacy+1);consolidated++;}else if(rival.gold>=6){rival.gold-=6;let push=2+(rival.levies>game.levies+8?1:0)-(game.standing>=2?1:0);game.threat=clamp(game.threat+Math.max(1,push));challenged++;}}game.gold=Math.max(0,game.gold+8+game.incomeBonus+Math.floor(game.cohesion/35));game.influence=clamp(game.influence+1,0,9);game.cohesion=clamp(game.cohesion+(game.legitimacy>=75?1:0)-(game.legitimacy<40?3:0));if(game.threat>=70)game.legitimacy=clamp(game.legitimacy-2);if(game.cohesion<25)game.legitimacy=clamp(game.legitimacy-2);const rivalActs=[mustered?`mustered ${mustered} time${mustered===1?'':'s'}`:'',consolidated?`consolidated ${consolidated} time${consolidated===1?'':'s'}`:'',challenged?`pressed claims ${challenged} time${challenged===1?'':'s'}`:''].filter(Boolean).join(', ')||'reorganized its court';addChronicle(`${seasonName(oldDate)} season resolved`,`Rival courts ${rivalActs}. Your treasury receives seasonal revenue; court cohesion and political influence are updated.`);const year=d.getUTCFullYear(),month=d.getUTCMonth(),markerKey=`${game.ruler}-${year}-${month}`;const marker=(game.ruler==='harold'&&year===1066&&month===9)||(game.ruler==='iziaslav'&&year===1068&&month===9)||(game.ruler==='constantine'&&year===1067&&month===6);if(marker&&game.lastMarker!==markerKey){const note=rulers[game.ruler].events[2];addChronicle(note[1],note[2]+' Historical context only: this date does not force the campaign outcome.');game.lastMarker=markerKey;}renderGame();saveGame();}
 function chooseRuler(id){if(!rulers[id])return;chosenRuler=id;renderSetup();}
 function route(action){if(action==='new'||action==='scenarios')enterApp('setup');else if(action==='settings')settingsScreen();else if(action==='continue'){if(!loadGame())showEmpty('continue')}else if(action==='load')showEmpty('load')}
