 document.addEventListener('input',e=>{if(e.target.matches('.range'))localStorage.setItem('ch-detail',e.target.value)});
 document.getElementById('appBack').addEventListener('click',()=>{if(campaignApp.dataset.screen==='game'){campaignApp.dataset.screen='setup';renderSetup()}else exitApp()});
 // Pan and zoom are handled on the SVG scene so mouse, pen, and Android touch all use the same path.
 const map=document.getElementById('campaignMap'),shell=document.getElementById('mapShell'),scene=document.createElementNS('http://www.w3.org/2000/svg','g');scene.id='mapScene';while(map.firstChild){scene.appendChild(map.firstChild)}map.appendChild(scene);let view={x:0,y:0,s:1},pointers=new Map(),drag=null,pinch=null;function applyView(){scene.setAttribute('transform',`translate(${view.x} ${view.y}) scale(${view.s})`)}function toSvg(e){const p=map.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(map.getScreenCTM().inverse())}function zoomAt(factor,c){const old=view.s;view.s=Math.max(.82,Math.min(4,old*factor));view.x=c.x-(c.x-view.x)*(view.s/old);view.y=c.y-(c.y-view.y)*(view.s/old);applyView()}function resetMap(){view={x:0,y:0,s:1};applyView()}map.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});map.setPointerCapture(e.pointerId);if(pointers.size===1){drag={id:e.pointerId,x:e.clientX,y:e.clientY,tx:view.x,ty:view.y};map.classList.add('dragging')}else if(pointers.size===2){const a=[...pointers.values()];pinch={distance:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),mid:toSvg({clientX:(a[0].x+a[1].x)/2,clientY:(a[0].y+a[1].y)/2})};drag=null}});map.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const a=[...pointers.values()],distance=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);zoomAt(distance/pinch.distance,pinch.mid);pinch={distance,mid:toSvg({clientX:(a[0].x+a[1].x)/2,clientY:(a[0].y+a[1].y)/2})}}else if(drag&&drag.id===e.pointerId){const rect=map.getBoundingClientRect(),unit=Math.min(rect.width/780,rect.height/590);view.x=drag.tx+(e.clientX-drag.x)/unit;view.y=drag.ty+(e.clientY-drag.y)/unit;applyView()}});function releasePointer(e){pointers.delete(e.pointerId);if(pointers.size<2)pinch=null;if(!pointers.size){drag=null;map.classList.remove('dragging')}}map.addEventListener('pointerup',releasePointer);map.addEventListener('pointercancel',releasePointer);map.addEventListener('wheel',e=>{e.preventDefault();zoomAt(e.deltaY<0?1.12:.89,toSvg(e))},{passive:false});document.getElementById('zoomIn').addEventListener('click',()=>zoomAt(1.25,{x:490,y:295}));document.getElementById('zoomOut').addEventListener('click',()=>zoomAt(.8,{x:490,y:295}));document.getElementById('mapReset').addEventListener('click',resetMap);

